// Parse into clean records
const parsedGames = [];
for (const g of games) {
  const dateMatch = g.date.match(/(\d{2})\.(\d{2})/);
  if (!dateMatch) continue;
  const month = parseInt(dateMatch[1], 10);
  const day = parseInt(dateMatch[2], 10);
  // day index for sorting: July 1 = 1, July 31 = 31, Aug 1 = 32, etc.
  const dayIndex = (month === 7 ? 0 : 31) + day;

  const cleanPlay = g.play.replace(/\d+/g, '');
  const parts = cleanPlay.split('vs');
  if (parts.length !== 2) continue;
  const away = parts[0].trim();
  const home = parts[1].trim();

  let venueKey = g.stadium;
