    venueKey = `잠실_${home}`;
  }
  if (!venueInfo[venueKey]) continue;

  parsedGames.push({
    month,
    day,
    dayIndex,
    dateStr: `${month.toString().padStart(2, '0')}.${day.toString().padStart(2, '0')}`,
    fullDate: g.date,
    time: g.time,
    stadium: g.stadium,
    venueKey,
    away,
    home,
    rawPlay: g.play
  });
}

