    "수원": { city: "Suwon", name: "Suwon KT Wiz Park", team: "KT Wiz", coord: cityCoords["Suwon"] },
    "대전": { city: "Daejeon", name: "Daejeon Hanwha Life Ballpark", team: "Hanwha Eagles", coord: cityCoords["Daejeon"] },
