const tabId = 787783793;

const allMonthsStadiums = await browserjs(tabId, async () => {
  const months = ['03', '04', '05', '06', '07', '08', '09', '10'];
  const allStadiums = new Set();
  const byMonth = {};

  for (const m of months) {
    $('#ddlMonth').val(m).trigger('change');
    await new Promise(r => setTimeout(r, 800));
    const rows = Array.from(document.querySelectorAll('.tbl-type06 tbody tr, table.tbl tbody tr'));
    const monthStadiums = new Set();
    for (const r of rows) {
      const tds = Array.from(r.querySelectorAll('td')).map(td => td.textContent.trim());
      const stadium = tds.length >= 2 ? tds[tds.length - 2] : "";
      if (stadium && stadium !== "-") {
        allStadiums.add(stadium);
        monthStadiums.add(stadium);
      }
    }
    byMonth[m] = Array.from(monthStadiums);
  }

  return { allStadiums: Array.from(allStadiums), byMonth };
});

console.log("All stadiums across all months:", allMonthsStadiums.allStadiums);
console.log("By month:", allMonthsStadiums.byMonth);

