const tabId = 787783793;

// Let's get the entire schedule structure for July and August with parsed team names
const scheduleAnalysis = await browserjs(tabId, async () => {
  const getGames = async (m) => {
    $('#ddlMonth').val(m).trigger('change');
    await new Promise(r => setTimeout(r, 1200));
    const rows = Array.from(document.querySelectorAll('.tbl-type06 tbody tr, table.tbl tbody tr'));
    let curDate = "";
    const list = [];
    for (const r of rows) {
      const dateTd = r.querySelector('.day');
      if (dateTd && dateTd.textContent.trim()) {
        curDate = dateTd.textContent.trim();
      }
      const tds = Array.from(r.querySelectorAll('td')).map(td => td.textContent.trim());
      const stadium = tds.length >= 2 ? tds[tds.length - 2] : "";
      const time = r.querySelector('.time')?.textContent.trim() || tds[1];
      const play = r.querySelector('.play')?.textContent.trim() || tds[2];
      list.push({ month: m, date: curDate, time, play, stadium });
    }
    return list;
  };

  const july = await getGames('07');
  const aug = await getGames('08');
  return [...july, ...aug];
});

// Let's analyze the games by date and stadium
const gamesByDate = {};
for (const g of scheduleAnalysis) {
  // Extract date like "07.01", "07.02", etc.
  const m = g.date.match(/(\d{2}\.\d{2})/);
  if (!m) continue;
  const d = m[1];
  if (!gamesByDate[d]) gamesByDate[d] = [];

  // parse play: e.g. "롯데5vs2두산" -> away: 롯데, home: 두산
  // or "LG vs 두산"
  const playClean = g.play.replace(/\d+/g, '');
  const parts = playClean.split('vs');
  const away = parts[0]?.trim();
  const home = parts[1]?.trim();

  gamesByDate[d].push({
    time: g.time,
    stadium: g.stadium,
    away,
    home,
    rawPlay: g.play
  });
}

console.log("Unique dates found:", Object.keys(gamesByDate).length);
console.log("Dates sample:", Object.keys(gamesByDate).slice(0, 15));

