      const play = r.querySelector('.play')?.textContent.trim() || tds[2];
      list.push({ month: m, date: curDate, time, play, stadium });
    }
    return list;
  };

  const july = await getGames('07');
  const aug = await getGames('08');
  return [...july, ...aug];
});

// Let's clean and parse each game
const cleanGames = [];
for (const g of gamesList) {
  const dateMatch = g.date.match(/(\d{2}\.\d{2})/);
  if (!dateMatch) continue;
  const dateStr = dateMatch[1]; // e.g. "07.01"

  // parse play
  // e.g. "롯데5vs2두산" or "롯데vs두산"
  const cleanPlay = g.play.replace(/\d+/g, '');
  const parts = cleanPlay.split('vs');
  if (parts.length !== 2) continue;
  const away = parts[0].trim();
  const home = parts[1].trim();

  // Let's identify the venue key:
  // For Jamsil, whether home is LG or Doosan:
  let venueKey = g.stadium;
  if (g.stadium === "잠실") {
    venueKey = `잠실_${home}`;
  }

  cleanGames.push({
    dateStr,
    fullDate: g.date,
    time: g.time,
    stadium: g.stadium,
    away,
    home,
    venueKey,
    rawPlay: g.play
  });
}

console.log("Total parsed clean games:", cleanGames.length);

// Let's verify our 10 venue keys:
// 1. 고척 (Kiwoom)
