      const time = r.querySelector('.time')?.textContent.trim() || tds[1];
      const play = r.querySelector('.play')?.textContent.trim() || tds[2];
      list.push({ month: m, date: curDate, time, play, stadium });
    }
    return list;
  };

  const july = await getGames('07');
  const aug = await getGames('08');
  const games = [...july, ...aug];

  const venueInfo = {
    "고척": { city: "Seoul", name: "Gocheok Sky Dome", team: "Kiwoom Heroes", x: 37.5, y: 126.87 },
    "잠실_LG": { city: "Seoul", name: "Jamsil Baseball Stadium", team: "LG Twins", x: 37.51, y: 127.07 },
    "잠실_두산": { city: "Seoul", name: "Jamsil Baseball Stadium", team: "Doosan Bears", x: 37.51, y: 127.07 },
    "문학": { city: "Incheon", name: "Incheon SSG Landers Field", team: "SSG Landers", x: 37.44, y: 126.69 },
    "수원": { city: "Suwon", name: "Suwon KT Wiz Park", team: "KT Wiz", x: 37.30, y: 127.01 },
    "대전": { city: "Daejeon", name: "Daejeon Hanwha Life Ballpark", team: "Hanwha Eagles", x: 36.32, y: 127.43 },
    "대구": { city: "Daegu", name: "Daegu Samsung Lions Park", team: "Samsung Lions", x: 35.84, y: 128.68 },
    "광주": { city: "Gwangju", name: "Gwangju-Kia Champions Field", team: "KIA Tigers", x: 35.17, y: 126.89 },
    "창원": { city: "Changwon", name: "Changwon NC Park", team: "NC Dinos", x: 35.22, y: 128.58 },
    "사직": { city: "Busan", name: "Busan Sajik Baseball Stadium", team: "Lotte Giants", x: 35.19, y: 129.06 }
  };

  const parsed = [];
  for (const g of games) {
    const dateMatch = g.date.match(/(\d{2})\.(\d{2})/);
    if (!dateMatch) continue;
    const month = parseInt(dateMatch[1], 10);
    const day = parseInt(dateMatch[2], 10);
    const dayIndex = (month === 7 ? 0 : 31) + day;

    const cleanPlay = g.play.replace(/\d+/g, '');
    const parts = cleanPlay.split('vs');
    if (parts.length !== 2) continue;
    const away = parts[0].trim();
