    // Check if all 10 venueKeys are present
    const venuesInWindow = new Set(windowGames.map(p => p.venueKey));
    if (venuesInWindow.size < 10) continue;

    // Backtrack to find valid sequence: 1 game per day, 10 distinct venues
    const findRoutes = (dayIdxPos, currentRoute, visitedVenues) => {
      if (results.length > 50) return;
      if (currentRoute.length === 10) {
        // Calculate total distance
        let totalD = 0;
        for (let i = 0; i < 9; i++) {
          totalD += dist(currentRoute[i].coord, currentRoute[i+1].coord);
        }
        results.push({
          spanDays: currentRoute[9].dayIndex - currentRoute[0].dayIndex + 1,
          totalDist: Math.round(totalD),
          route: currentRoute
        });
        return;
      }
      if (dayIdxPos >= windowDays.length) return;
      // Remaining venues needed: 10 - currentRoute.length
      // Remaining days available: windowDays.length - dayIdxPos
      if (10 - currentRoute.length > windowDays.length - dayIdxPos) return;

      const thisDay = windowDays[dayIdxPos];
      const todayGames = windowGames.filter(g => g.dayIndex === thisDay);

      // Option 1: Pick a game today
      for (const g of todayGames) {
        if (!visitedVenues.has(g.venueKey)) {
          visitedVenues.add(g.venueKey);
          currentRoute.push(g);
          findRoutes(dayIdxPos + 1, currentRoute, visitedVenues);
          currentRoute.pop();
          visitedVenues.delete(g.venueKey);
        }
      }

      // Option 2: Skip today (rest/travel day)
      findRoutes(dayIdxPos + 1, currentRoute, visitedVenues);
    };

    findRoutes(0, [], new Set());
    if (results.length >= 20) break;
  }

  // Sort by totalDist
  results.sort((a, b) => a.totalDist - b.totalDist);
  return results.slice(0, 5);
});

