const tabId = 787783793;

// Let's write an exact pathfinder between Aug 4 and Aug 28
const pathfinder = await browserjs(tabId, () => {
  // Candidate games by date
  // We want to pick 10 games, each at a distinct venue:
  // 1. 고척 (Kiwoom)
  // 2. 문학 (SSG - Incheon)
  // 3. 수원 (KT - Suwon)
  // 4. 잠실_LG (LG - Seoul)
  // 5. 잠실_두산 (Doosan - Seoul)
  // 6. 대전 (Hanwha - Daejeon)
  // 7. 대구 (Samsung - Daegu)
  // 8. 광주 (KIA - Gwangju)
  // 9. 창원 (NC - Changwon)
  // 10. 사직 (Lotte - Busan)

  const cityCoords = {
    "Seoul": [37.5665, 126.9780],
    "Incheon": [37.4563, 126.7052],
    "Suwon": [37.2636, 127.0286],
    "Daejeon": [36.3504, 127.3845],
    "Daegu": [35.8714, 128.6014],
    "Busan": [35.1796, 129.0756],
    "Changwon": [35.2280, 128.6811],
    "Gwangju": [35.1595, 126.8526]
  };

  const venues = {
    "고척": { city: "Seoul", name: "Gocheok Sky Dome", team: "Kiwoom Heroes", coord: cityCoords["Seoul"] },
    "잠실_LG": { city: "Seoul", name: "Jamsil Baseball Stadium (LG Twins)", team: "LG Twins", coord: cityCoords["Seoul"] },
    "잠실_두산": { city: "Seoul", name: "Jamsil Baseball Stadium (Doosan Bears)", team: "Doosan Bears", coord: cityCoords["Seoul"] },
    "문학": { city: "Incheon", name: "Incheon SSG Landers Field", team: "SSG Landers", coord: cityCoords["Incheon"] },
    "수원": { city: "Suwon", name: "Suwon KT Wiz Park", team: "KT Wiz", coord: cityCoords["Suwon"] },
    "대전": { city: "Daejeon", name: "Daejeon Hanwha Life Ballpark", team: "Hanwha Eagles", coord: cityCoords["Daejeon"] },
    "대구": { city: "Daegu", name: "Daegu Samsung Lions Park", team: "Samsung Lions", coord: cityCoords["Daegu"] },
    "광주": { city: "Gwangju", name: "Gwangju-Kia Champions Field", team: "KIA Tigers", coord: cityCoords["Gwangju"] },
    "창원": { city: "Changwon", name: "Changwon NC Park", team: "NC Dinos", coord: cityCoords["Changwon"] },
    "사직": { city: "Busan", name: "Busan Sajik Baseball Stadium", team: "Lotte Giants", coord: cityCoords["Busan"] }
  };

  // Distance helper
  const dist = (c1, c2) => {
    const dx = (c1[0] - c2[0]) * 111;
    const dy = (c1[1] - c2[1]) * 88;
    return Math.sqrt(dx*dx + dy*dy);
  };

  // Let's list all available games for each date in August
  // We have parsed series blocks:
  // Aug 4-6 (Tue-Thu):
  //   잠실_두산: NC vs Doosan
  //   대구: 한화 vs Samsung
  //   사직: 키움 vs Lotte
  //   문학: LG vs SSG
  //   광주: KT vs KIA
  // Aug 7-9 (Fri-Sun):
  //   잠실_LG: KIA vs LG
  //   대구: 두산 vs Samsung
  //   수원: 롯데 vs KT
  //   창원: SSG vs NC
  //   대전: 키움 vs Hanwha
  // Aug 11-13 (Tue-Thu):
  //   잠실_두산: 한화 vs Doosan
  //   문학: 롯데 vs SSG
  //   광주: 삼성 vs KIA
  //   창원: KT vs NC
  //   고척: LG vs Kiwoom
  // Aug 14-16 (Fri-Sun):
  //   잠실_LG: SSG vs LG
  //   대구: 한화 vs Samsung
  //   사직: NC vs Lotte
  //   광주: 두산 vs KIA
  //   수원: 키움 vs KT
  // Aug 18-20 (Tue-Thu):
  //   잠실_LG: KT vs LG
  //   대구: SSG vs Samsung
  //   사직: 키움 vs Lotte
  //   창원: 두산 vs NC
  //   대전: KIA vs Hanwha
  // Aug 21-23 (Fri-Sun):
  //   잠실_두산: 롯데 vs Doosan
  //   문학: KT vs SSG
  //   창원: 삼성 vs NC
  //   대전: LG vs Hanwha
  //   고척: KIA vs Kiwoom
  // Aug 25-27 (Tue-Thu):
  //   잠실_LG: NC vs LG
  //   문학: 한화 vs SSG
  //   광주: 롯데 vs KIA
  //   수원: 두산 vs KT
  //   고척: 삼성 vs Kiwoom
  // Aug 28-30 (Fri-Sun):
  //   잠실_두산: 키움 vs Doosan
  //   대구: KT vs Samsung
  //   사직: LG vs Lotte
  //   광주: SSG vs KIA
  //   대전: NC vs Hanwha

  // Let's test specific clean geographic sequences!
  // Look at this natural flow:
  // Leg 1: Seoul/Capital (Aug 4 - Aug 11) or (Aug 7 - Aug 16)
  // Let's test candidate sequences that pick 1 game per series or consecutive dates:
  // e.g.:
  // Can we do:
  // 1. Aug 4 (Tue) - 문학 (Incheon): LG vs SSG
  // 2. Aug 5 (Wed) - 잠실_두산 (Seoul): NC vs Doosan
  // 3. Aug 7 (Fri) - 수원 (Suwon): 롯데 vs KT
  // 4. Aug 8 (Sat) - 대전 (Daejeon): 키움 vs Hanwha
  // 5. Aug 11 (Tue) - 고척 (Seoul): LG vs Kiwoom (Wait, going back to Seoul?)
  // Let's write an exhaustive search over valid sequences of 10 games (one per venue) chosen from Aug 1 to Aug 30!

  // Let's build the full game table for August:
  const allAugGames = [];
  const rows = Array.from(document.querySelectorAll('.tbl-type06 tbody tr, table.tbl tbody tr'));
  let curDate = "";
  for (const r of rows) {
    const dateTd = r.querySelector('.day');
    if (dateTd && dateTd.textContent.trim()) curDate = dateTd.textContent.trim();
    const tds = Array.from(r.querySelectorAll('td')).map(td => td.textContent.trim());
    const stadium = tds.length >= 2 ? tds[tds.length - 2] : "";
    const time = r.querySelector('.time')?.textContent.trim() || tds[1];
    const play = r.querySelector('.play')?.textContent.trim() || tds[2];

    const cleanPlay = play.replace(/\d+/g, '');
    const parts = cleanPlay.split('vs');
    if (parts.length !== 2) continue;
    const away = parts[0].trim();
    const home = parts[1].trim();
    let venueKey = stadium;
    if (stadium === "잠실") venueKey = `잠실_${home}`;
    if (!venues[venueKey]) continue;

    const m = curDate.match(/08\.(\d{2})/);
    if (!m) continue;
    const day = parseInt(m[1], 10);

    allAugGames.push({
      day,
      date: curDate,
      time,
      venueKey,
      stadium,
      away,
      home,
      city: venues[venueKey].city,
      coord: venues[venueKey].coord,
      matchup: `${away} vs ${home}`
    });
  }

  // Let's find valid combinations of 10 games with 1 per venueKey, where day is strictly increasing
  const venueKeys = Object.keys(venues);
  const gamesByVenue = {};
  for (const vk of venueKeys) {
    gamesByVenue[vk] = allAugGames.filter(g => g.venueKey === vk);
  }

  // We want to minimize total distance and ensure day_i < day_{i+1}
  // Let's run a search across permutations of venue orders that have low distance:
  // Natural orders:
  // Order A (North to South then West):
  // Seoul/Incheon/Suwon -> Daejeon -> Daegu -> Busan -> Changwon -> Gwangju
  // Order B (Seoul/Incheon/Suwon -> Gwangju -> Changwon -> Busan -> Daegu -> Daejeon)
  // Let's test low-distance permutations of cities:
  // e.g. [Gocheok, Incheon, Suwon, Jamsil_LG, Daejeon, Daegu, Busan, Changwon, Gwangju, Jamsil_Doosan] etc.

  const candidateRoutes = [];

  // Helper to find valid game dates for a given ordered list of 10 venues
  const evaluateVenueOrder = (order) => {
    // DFS to find dates
    const findDates = (idx, minDay, current) => {
      if (idx === 10) {
        let totalD = 0;
        for (let i = 0; i < 9; i++) {
          totalD += dist(current[i].coord, current[i+1].coord);
        }
        candidateRoutes.push({
          totalDist: Math.round(totalD),
          span: current[9].day - current[0].day + 1,
          games: [...current]
        });
        return;
      }
      if (candidateRoutes.length > 200) return;
      const vk = order[idx];
      const available = gamesByVenue[vk].filter(g => g.day > minDay);
      for (const g of available) {
        current.push(g);
        findDates(idx + 1, g.day, current);
        current.pop();
      }
    };
    findDates(0, 0, []);
  };

  // Test some geographically smooth orders:
  const testOrders = [
    // Starting in capital area, going down through Daejeon -> Daegu -> Busan -> Changwon -> Gwangju
    ["고척", "문학", "잠실_LG", "수원", "대전", "대구", "사직", "창원", "광주", "잠실_두산"],
    ["잠실_LG", "고척", "문학", "수원", "대전", "대구", "사직", "창원", "광주", "잠실_두산"],
    ["문학", "고척", "잠실_두산", "수원", "대전", "대구", "사직", "창원", "광주", "잠실_LG"],
    ["고척", "문학", "수원", "잠실_LG", "대전", "대구", "사직", "창원", "광주", "잠실_두산"],
    ["고척", "잠실_두산", "문학", "수원", "대전", "대구", "창원", "사직", "광주", "잠실_LG"],
    ["잠실_두산", "고척", "문학", "수원", "대전", "대구", "사직", "창원", "광주", "잠실_LG"],
    ["잠실_두산", "문학", "고척", "수원", "대전", "대구", "사직", "창원", "광주", "잠실_LG"],
    ["잠실_두산", "문학", "수원", "대전", "대구", "사직", "창원", "광주", "고척", "잠실_LG"],
    // Starting south or doing Honam first:
    ["잠실_LG", "문학", "고척", "수원", "대전", "광주", "창원", "사직", "대구", "잠실_두산"],
    ["고척", "문학", "잠실_두산", "수원", "대전", "광주", "창원", "사직", "대구", "잠실_LG"]
  ];

  for (const o of testOrders) {
    evaluateVenueOrder(o);
  }

  candidateRoutes.sort((a, b) => a.totalDist - b.totalDist || a.span - b.span);
  return { count: candidateRoutes.length, best: candidateRoutes.slice(0, 3) };
});

console.log("Found candidate routes:", pathfinder.count);
if (pathfinder.best && pathfinder.best.length > 0) {
  console.log("BEST ROUTE:");
  console.log("Total dist:", pathfinder.best[0].totalDist, "km | Span:", pathfinder.best[0].span, "days");
  pathfinder.best[0].games.forEach((g, i) => {
    console.log(`${i+1}. ${g.date} (${g.time}) - ${g.city} [${g.stadium}]: ${g.matchup} (${g.venueKey})`);
  });
}

