      away,
      home,
      city: venues[venueKey].city,
      coord: venues[venueKey].coord,
      matchup: `${away} vs ${home}`
    });
  }

  // Let's find valid combinations of 10 games with 1 per venueKey, where day is strictly increasing
  const venueKeys = Object.keys(venues);
  const gamesByVenue = {};
  for (const vk of venueKeys) {
    gamesByVenue[vk] = allAugGames.filter(g => g.venueKey === vk);
