  { stop: 2, query: "site:booking.com/hotel/kr near Gocheok Sky Dome" },
  { stop: 3, query: "site:booking.com/hotel/kr near Incheon Munhak Stadium" },
  { stop: 4, query: "site:booking.com/hotel/kr near Suwon KT Wiz Park" },
  { stop: 5, query: "site:booking.com/hotel/kr near Hanwha Life Eagles Park Daejeon" },
  { stop: 6, query: "site:booking.com/hotel/kr near Daegu Samsung Lions Park" },
  { stop: 7, query: "site:booking.com/hotel/kr near Busan Sajik Baseball Stadium" },
  { stop: 8, query: "site:booking.com/hotel/kr near Changwon NC Park Masan" },
  { stop: 9, query: "site:booking.com/hotel/kr near Gwangju Kia Champions Field" },
  { stop: 10, query: "site:booking.com/hotel/kr near COEX Samseong Jamsil Seoul" }
];

const foundHotels = [];

for (const q of searchQueries) {
  await tool.navigate({ tabId, url: `https://www.google.com/search?q=${encodeURIComponent(q.query)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });
  await new Promise(r => setTimeout(r, 1200));

  const items = await browserjs(tabId, () => {
    const list = [];
    const headings = Array.from(document.querySelectorAll('h3'));
    for (const h of headings) {
      const a = h.closest('a');
      if (a && a.href) {
        list.push({ title: h.textContent.trim(), href: a.href });
      }
    }
    return list;
  });

  foundHotels.push({ stop: q.stop, query: q.query, results: items.slice(0, 3) });
}

console.log(JSON.stringify(foundHotels, null, 2));

