const tabId = 787783793;

// Let's search Yelp on Google or directly on yelp.com
// Let's check Google search for site:yelp.com restaurants in Seoul, Busan, Incheon, etc.
const foodSearches = [
  { city: "Seoul", term: "site:yelp.com Korean fried chicken Jamsil Seoul" },
  { city: "Incheon", term: "site:yelp.com Jajangmyeon Chinatown Incheon" },
  { city: "Suwon", term: "site:yelp.com Suwon Galbi ribs chicken" },
  { city: "Daejeon", term: "site:yelp.com Sung Sim Dang Daejeon" },
  { city: "Daegu", term: "site:yelp.com Daegu Makchang Korean BBQ" },
  { city: "Busan", term: "site:yelp.com Dwaeji Gukbap Busan" },
  { city: "Gwangju", term: "site:yelp.com Songjeong Tteokgalbi Gwangju" }
];

const yelpResults = [];

for (const s of foodSearches) {
  await tool.navigate({ tabId, url: `https://www.google.com/search?q=${encodeURIComponent(s.term)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });
  await new Promise(r => setTimeout(r, 1000));

  const items = await browserjs(tabId, () => {
    const list = [];
    const headings = Array.from(document.querySelectorAll('h3'));
    for (const h of headings) {
      const a = h.closest('a');
      if (a && a.href) {
        list.push({ title: h.textContent.trim(), href: a.href });
      }
    }
    return list;
  });

  yelpResults.push({ city: s.city, term: s.term, results: items.slice(0, 3) });
}

console.log(JSON.stringify(yelpResults, null, 2));

