  { city: "Seoul Gocheok", stadium: "Gocheok Sky Dome", query: "best food Gocheok Sky Dome cream shrimp Guro" },
  { city: "Incheon", stadium: "Incheon SSG Landers Field", query: "famous food Incheon Chinatown jajangmyeon Sinpo dakgangjeong" },
  { city: "Suwon", stadium: "Suwon KT Wiz Park", query: "Suwon famous food Wang galbi fried chicken street Jangan" },
  { city: "Daejeon", stadium: "Daejeon Hanwha Life Ballpark", query: "Daejeon famous food Sung Sim Dang bakery kalguksu Hanwha" },
  { city: "Daegu", stadium: "Daegu Samsung Lions Park", query: "Daegu famous food Anjirang makchang Dongin dong jjimgalbi" },
  { city: "Busan", stadium: "Busan Sajik Baseball Stadium", query: "Busan famous food Sajik stadium Dwaeji gukbap milmyeon" },
  { city: "Changwon", stadium: "Changwon NC Park", query: "Changwon Masan famous food Agujjim fish market NC park" },
  { city: "Gwangju", stadium: "Gwangju-Kia Champions Field", query: "Gwangju famous food Songjeong tteokgalbi oritang champions field" },
  { city: "Seoul Gangnam", stadium: "Jamsil / COEX", query: "best Korean BBQ restaurant Samseong dong COEX Seoul" }
];

const foodResearch = [];

for (const cf of cityFoods) {
  await tool.navigate({ tabId, url: `https://www.google.com/search?q=${encodeURIComponent(cf.query)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });
  await new Promise(r => setTimeout(r, 1200));

  const snippets = await browserjs(tabId, () => {
    const results = [];
    const elements = Array.from(document.querySelectorAll('div[data-snc], .MjjYud, .g'));
    for (const el of elements.slice(0, 3)) {
      const title = el.querySelector('h3')?.textContent?.trim();
      const text = el.innerText.replace(/\s+/g, ' ').trim();
      if (title && text.length > 50) {
        results.push({ title, snippet: text.slice(0, 300) });
      }
    }
    return results;
  });

  foodResearch.push({ city: cf.city, stadium: cf.stadium, results: snippets });
}

console.log(JSON.stringify(foodResearch, null, 2));

